/**
 * The balloon bunch: the supplied studio artwork, cropped and inlined.
 *
 * Inlined as a data URI rather than imported as an asset, for the reason
 * `utils/svgExport` spells out: the card is rasterised by handing the serialised SVG to
 * `new Image()`, and an SVG loaded as an image is an isolated document that fetches
 * NOTHING -- not a stylesheet, not a webfont, not a bundled PNG sitting next to it. A
 * normal Vite asset import would appear in the on-screen preview and then be missing from
 * every downloaded card.
 *
 * ONE bunch, not the pair the file was supplied as. The source is a bunch beside its own
 * mirror image, and the card already draws each side with a mirror transform, so cropping
 * the left one halves the bytes and makes the two sides match by construction.
 *
 * Cropped to 546 x 812 out of 1536 x 1024, dropping 200 rows of thin trailing ribbon
 * below the balloons -- mostly-empty image that would otherwise have forced the bunch to
 * be drawn small just to fit its own aspect ratio. WebP at q85: 188 KB inline, against
 * 868 KB for the same crop as PNG.
 *
 * Regenerate from `balloons.png`, kept beside this file as the source of truth.
 */
export const BALLOONS = {
  width: 546,
  height: 812,
  href: "data:image/webp;base64,",
};
